import{_ as t,o,c as r,j as e,a as s}from"./chunks/framework.DdpBa4_E.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/78-下决心改变心态.md","filePath":"books/attached/78-下决心改变心态.md","lastUpdated":1794316978000}'),n={name:"books/attached/78-下决心改变心态.md"};function d(l,a,c,_,p,i){return o(),r("div",null,[...a[0]||(a[0]=[e("h3",{id:"下决心改变心态",tabindex:"-1"},[s("下决心改变心态 "),e("a",{class:"header-anchor",href:"#下决心改变心态","aria-label":'Permalink to "下决心改变心态"'},"​")],-1),e("p",null,"那么这种通过降低期待化解冲突的方法，到底是否值得推崇呢？我们的答案是：具体情况具体分析。如果你刚好处于难以解决的亲密关系冲突之中，并且无论如何都想继续这段关系，那这或许是你获得安稳关系的唯一途径了。但是你在亲密关系中的满意度，就会低于那些不需要与这些问题做斗争的人们。但是相比于那些存在着根本分歧，却不接受这种差异，每天不断因此争吵的情侣来说，当然还是要好一些。",-1),e("p",null,"不过，如果你刚开始一段关系，感情尚且还不成熟，就已经感觉到许多的亲密冲突了，那么就建议长远考虑这段关系，权衡自己是否真的愿意为了和这个人在一起，而做出如此大的让步。因为在亲密关系中，由于依恋分歧而造成的争吵，与普通的恋人争吵完全不同的。一般的情侣发生争吵，他们会努力通过达成共识而解决问题，这会令他们更加亲密。而因为依恋风格的分歧而产生的争吵是无休无止的，唯一的出路就是逼迫其中的一方，为了自己心爱的人而步步退让。",-1),e("p",null,"可是，一旦妥协失去了原则，依恋冲突会致使关系不断恶化。下一章就会讲述亲密冲突是如何失控的，以及如何认清当前的形势，更重要的是，如何抛开这些苦恼。",-1)])])}const h=t(n,[["render",d]]);export{f as __pageData,h as default};
